import { existsSync, writeFileSync } from "node:fs";
import { randomBytes } from "node:crypto";

const path = new URL("../.dev.vars", import.meta.url);

if (!existsSync(path)) {
  const ownerToken = randomToken();
  const editorToken = randomToken();
  const bootstrapToken = randomToken();
  const content = [
    "# Generated by npm run dev. Values are instance-local development secrets.",
    "DOWNWRITE_LOCAL_AUTH=1",
    `DEVELOPMENT_API_TOKENS=dev-owner:${ownerToken},dev-editor:${editorToken}`,
    `AUTH_BOOTSTRAP_TOKEN=${bootstrapToken}`,
    "WEBAUTHN_RP_NAME=Downwrite",
    "",
  ].join("\n");

  writeFileSync(path, content, { mode: 0o600 });
  console.log("Created worker/.dev.vars with generated local secrets.");
} else {
  console.log("Using existing worker/.dev.vars.");
}

function randomToken() {
  return randomBytes(24).toString("base64url");
}
